"""Run four fixed, isolated reachability diagnostics; these are never latency samples."""
import argparse
import importlib.util
import json
import os
from pathlib import Path
import shutil

HERE = Path(__file__).resolve().parent
PHASE = HERE.parent


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--runtime', required=True, type=Path)
    parser.add_argument('--output', required=True, type=Path)
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if not args.slot_granted:
        raise ValueError('Exclusive Java slot required; never run concurrently with timing')
    spec = importlib.util.spec_from_file_location('retention_contract_runner', PHASE / 'contracts/run_contracts.py')
    helper = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(helper)
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    source = HERE / 'src/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeDirectMemoRetentionDiagnostic.java'
    shutil.copyfile(source, output / source.name)
    shutil.copyfile(__file__, output / 'runner-at-launch.py')
    classpath = (args.runtime / 'classpath.txt').read_text().strip()
    classes = output / 'classes'
    classes.mkdir()
    command = [helper.JAVA_HOME / 'bin/javac', '--release', '25', '-g', '-proc:none', '-implicit:none',
               '-sourcepath', '', '-cp', classpath, '-d', classes, output / source.name]
    compiled = helper.run(output, 'compile', command)
    if compiled['exitCode']:
        print((output / 'compile.log').read_text())
        raise RuntimeError('Memory diagnostic did not compile')
    helper.write(output / 'input-identities.json', {'sourceSha256': helper.digest(source),
        'classpathFile': str(args.runtime.resolve() / 'classpath.txt'),
        'classpathFileSha256': helper.digest(args.runtime / 'classpath.txt'),
        'runtimeClassFiles': helper.tree(args.runtime / 'classes'), 'diagnosticClasses': helper.tree(classes),
        'diagnosticOnly': True, 'forcedGcInTiming': False})
    results = []
    phases = ['empty_open', 'cold_with_consumers', 'initialized_with_consumers', 'open_after_consumer_release',
              'closed_with_consumer', 'closed_after_consumer_release']
    for retention, consumer in [('strong', 'none'), ('weak', 'none'), ('weak', 'one'), ('strong', 'one')]:
        out = output / (retention + '-' + consumer)
        out.mkdir()
        argv = [helper.JAVA_HOME / 'bin/java', '-Xms1024m', '-Xmx1024m', '-XX:+UseG1GC',
            '-XX:ObjectAlignmentInBytes=8', '-XX:+UseCompressedOops', '-XX:+UseCompressedClassPointers',
            '-Xlog:gc:file=' + str(out / 'gc.log') + ':uptime,level,tags',
            '-Drdf4j.lmdb.nativeValueMemo.retention=' + retention,
            '-cp', str(classes) + os.pathsep + classpath,
            'org.eclipse.rdf4j.sail.lmdb.evaluation.NativeDirectMemoRetentionDiagnostic', consumer]
        completed = helper.run(out, 'diagnostic', argv)
        rows = [json.loads(line) for line in (out / 'diagnostic.log').read_text().splitlines() if line.startswith('{')]
        checkpoints = [row for row in rows if row.get('record') == 'checkpoint']
        valid = (completed['exitCode'] == 0 and len(rows) == 7 and len(checkpoints) == 6
                 and [row['phase'] for row in checkpoints] == phases
                 and all(row['reachabilityMatchesExpected'] for row in checkpoints)
                 and all(row['memoProbes'] == 128 and row['memoHits'] == 64 and row['memoCollisions'] == 0
                         for row in checkpoints[1:])
                 and checkpoints[-1]['ledgerBytesAfterGc'] == 0)
        helper.write(out / 'observations.json', rows)
        result = {'retention': retention, 'consumer': consumer, 'passed': valid,
                  'observationsSha256': helper.digest(out / 'observations.json'),
                  'commandSha256': helper.digest(out / 'diagnostic-command.json'),
                  'checkpointCount': len(checkpoints)}
        helper.write(out / 'receipt.json', result)
        results.append(result)
        print(json.dumps(result), flush=True)
        if not valid:
            raise RuntimeError('Memory diagnostic failed; preserve the attempt and inspect its raw observations')
    helper.write(output / 'receipt.json', {'diagnosticOnly': True, 'passed': all(r['passed'] for r in results),
        'runs': results, 'freshJvms': 4, 'checkpoints': 24, 'pooledWithTiming': False})


if __name__ == '__main__':
    main()
